% The COBRAToolbox: testSlvrEMU.m
%
% Purpose:
%     - slvrEMU is the (unoptimised) EMU (elementary metabolite unit) solver generated by
%       generateIsotopomerSolver (Perl script generatorEMU.pl) for the E. coli isotopomer model of
%       testFitC13Data (model.mat, 335 reactions). Given a flux vector and the glucose label input
%       as mass distribution vectors (MDVs) of glucose fragments (convertCarbonInput), it solves
%       nine levels of sparse linear systems and returns the MDVs of 36 amino-acid fragments. The
%       test uses the fixtures of this folder: the steady-state flux vector v0 (point.mat) and the
%       label input of expdata.mat, and checks
%         * the 36 output fields and the length of each MDV (number of carbons in the fragment
%           name + 1), that each MDV sums to 1 and is nonnegative (MDVs are distributions);
%         * that an unlabelled glucose input gives the MDV [1 0 ... 0] for every fragment
%           (no 13C enters the network: independent derivation);
%         * agreement with the cumomer solver slvrCumomer_fast generated from the same model: the
%           fragment MDVs computed from its isotopomer distributions with idv2mdv must equal the
%           EMU results (different algorithm, so an independent check of the values);
%         * agreement with slvrEMU_fast, the optimised EMU solver generated from the same model.
%
% Function under test:
%     src/dataIntegration/fluxomics/c13solver/slvrEMU.m
%
% Tier (Constitution III-Coverage):
%     Tier 1 - no solver (the linear systems are solved by solveLin with backslash) and no
%     genome-scale model: the flux vector and label input are the small fixtures point.mat and
%     expdata.mat of this folder.
%
% Coverage exemptions:
%     None. Every executable line is reached below (the function is straight-line code).
%
% Known defects documented (NOT tested, NOT fixed here):
%     None found.
%
% Authors:
%     - Generated for feature 20261113-142115-test-backfill-tiers, 2026-11-15.

% save the current path
currentDir = pwd;

% initialize the test
fileDir = fileparts(which('testSlvrEMU'));
cd(fileDir);

% declare the requirements of this test. A Tier 1 test needs no solver, MATLAB toolbox
% or particular operating system, so none is listed; the call is the standard opening
% of a COBRA test and the place where a requirement would be added later
prepareTest();

% solveLin (called by the function) turns the warning MATLAB:nearlySingularMatrix off and does
% not turn it on again; save its state to restore it at the end
nearlySingularState = warning('query', 'MATLAB:nearlySingularMatrix');

% cdv2idv and idv2mdv (used by convertCarbonInput and below) cache matrices in global
% variables; note the globals that exist now to remove the new ones at the end
globalsBefore = who('global');

% fixtures of this folder (shared with testFitC13Data): the flux vector v0 of model.mat and
% the glucose label input expdata.input (cumomer vector of the 6 glucose carbons, converted to
% the MDVs of the 16 glucose fragments that the EMU solver reads)
load('point.mat', 'v0');
load('expdata.mat', 'expdata');
glucoseInput = convertCarbonInput(expdata.input);

% MDV entries are sums and products of fractions in [0, 1] obtained by sparse linear solves;
% observed rounding is below 1e-15 for the sums and 3e-12 between the solvers, so 1e-10
% separates rounding from a real change
tol = 1e-10;

%% output fields, MDV lengths, normalisation and nonnegativity

output = slvrEMU(v0, glucoseInput);
expectedNames = {'xalaL011'; 'xalaL111'; 'xasnL0111'; 'xasnL1100'; 'xasnL1111'; 'xaspL0111'; ...
    'xaspL1100'; 'xaspL1111'; 'xglnL01111'; 'xglnL11111'; 'xgluL01111'; 'xgluL11111'; ...
    'xgly01'; 'xgly11'; 'xhisL011111'; 'xhisL111111'; 'xileL011111'; 'xleuL011111'; ...
    'xlysL011111'; 'xlysL111111'; 'xmetL01111'; 'xmetL11111'; 'xpheL011111111'; ...
    'xpheL110000000'; 'xpheL111111111'; 'xproL01111'; 'xserL011'; 'xserL110'; 'xserL111'; ...
    'xthrL0111'; 'xthrL1111'; 'xtyrL011111111'; 'xtyrL110000000'; 'xtyrL111111111'; ...
    'xvalL01111'; 'xvalL11111'};
assert(isequal(fieldnames(output), expectedNames));
for k = 1:numel(expectedNames)
    fragmentName = expectedNames{k};
    mdv = output.(fragmentName);
    % the fragment name ends with one digit per carbon; 1 marks a carbon in the fragment,
    % so the MDV has (number of 1s + 1) mass isotopomers M+0 ... M+n
    carbonPattern = regexp(fragmentName, '[01]+$', 'match', 'once');
    assert(iscolumn(mdv) && numel(mdv) == nnz(carbonPattern == '1') + 1);
    % a mass distribution sums to one and has no negative fraction
    assert(abs(sum(mdv) - 1) < tol);
    assert(all(mdv > -tol));
end

%% an unlabelled glucose input leaves every fragment unlabelled

% all glucose molecules are the isotopomer 000000; the cumomer vector of this input is the
% one built by idv2cdv, as convertCarbonInput expects
unlabelledIdv = zeros(64, 1);
unlabelledIdv(1) = 1;
unlabelledOutput = slvrEMU(v0, convertCarbonInput(idv2cdv(6) * unlabelledIdv));
for k = 1:numel(expectedNames)
    mdv = unlabelledOutput.(expectedNames{k});
    expectedMdv = [1; zeros(numel(mdv) - 1, 1)];
    assert(max(abs(mdv - expectedMdv)) < tol);
end

%% agreement with the cumomer solver of the same model

% slvrCumomer_fast returns the isotopomer distribution of each whole amino acid; idv2mdv with
% the carbon pattern of the fragment name gives the mass distribution of the fragment
cumomerOutput = slvrCumomer_fast(v0, expdata.input);
for k = 1:numel(expectedNames)
    fragmentName = expectedNames{k};
    carbonPattern = regexp(fragmentName, '[01]+$', 'match', 'once');
    aminoAcid = fragmentName(1:end - numel(carbonPattern));
    fragment = double(carbonPattern' == '1');
    cumomerMdv = idv2mdv(numel(fragment), fragment) * cumomerOutput.(aminoAcid);
    assert(max(abs(output.(fragmentName) - cumomerMdv)) < tol);
end
clear cumomerOutput

%% agreement with the optimised EMU solver slvrEMU_fast of the same model

fastOutput = slvrEMU_fast(v0, glucoseInput);
for k = 1:numel(expectedNames)
    assert(max(abs(output.(expectedNames{k}) - fastOutput.(expectedNames{k}))) < tol);
end

% restore the warning state changed by solveLin
warning(nearlySingularState);

% remove the global caches created by cdv2idv and idv2mdv
newGlobals = setdiff(who('global'), globalsBefore);
for k = 1:numel(newGlobals)
    clearvars('-global', newGlobals{k});
end

% change the directory
cd(currentDir)
